import { useState, useEffect, useCallback } from "react";
import { io } from "socket.io-client";
import "./PatientDashboard.css";

const socket = io("http://localhost:5000");

function PatientDashboard() {

  const [form, setForm] = useState({
    patientName: "",
    department: "",
    date: ""
  });

  const [myOP, setMyOP] = useState(null);
  const [queues, setQueues] = useState([]);
  const [joined, setJoined] = useState(false);

  // 🔥 GET DATA
  const fetchData = useCallback(async () => {

    const res = await fetch("http://localhost:5000/api/queue/all");
    const data = await res.json();

    setQueues(data);

    const mine = data.find(
      q => q.patientName === form.patientName
    );

    if (mine) setMyOP(mine);
    else setMyOP(null);

  }, [form.patientName]);

  useEffect(() => {
    fetchData();
    socket.on("queueUpdated", fetchData);

    return () => socket.off("queueUpdated", fetchData);
  }, [fetchData]);

  // BOOK OP
  const bookOP = async () => {

    await fetch("http://localhost:5000/api/queue/book", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form)
    });

  };

  // JOIN QUEUE
  const joinQueue = async (id) => {

    await fetch(`http://localhost:5000/api/queue/join/${id}`, {
      method: "PUT"
    });

    setJoined(true); // 🔥 switch UI to queue list
  };

  return (

    <div className="patient-page">

      {/* 🔥 BOOK FORM */}
      {!myOP && (

        <div className="card">

          <h1 className="title">HealSync</h1>
          <p className="subtitle">Book Your OP Appointment</p>

          <input
            placeholder="Patient Name"
            onChange={(e) =>
              setForm({ ...form, patientName: e.target.value })
            }
          />

          <input
            placeholder="Department"
            onChange={(e) =>
              setForm({ ...form, department: e.target.value })
            }
          />

          <input
            type="date"
            onChange={(e) =>
              setForm({ ...form, date: e.target.value })
            }
          />

          <button onClick={bookOP}>
            Book OP
          </button>

        </div>

      )}

      {/* 🔥 OP CARD */}
      {myOP && !joined && (

        <div className="card">

          <h2>My OP Details</h2>

          <p><b>Name:</b> {myOP.patientName}</p>
          <p><b>Department:</b> {myOP.department}</p>
          <p><b>Status:</b> {myOP.status}</p>

          {myOP.status === "Confirmed" && (
            <button onClick={() => joinQueue(myOP._id)}>
              Join Queue
            </button>
          )}

        </div>

      )}

      {/* 🔥 LIVE QUEUE LIST (AFTER JOIN) */}
      {joined && (

        <div className="queue-card">

          <h2>Live OP Queue</h2>

          {queues.map((q, index) => (

            <div key={q._id} className="queue-item">

              <span className="token">
                #{index + 1}
              </span>

              <div>
                <p className="name">{q.patientName}</p>
                <p className="status">{q.status}</p>
              </div>

            </div>

          ))}

        </div>

      )}

    </div>

  );

}

export default PatientDashboard;
